  9→import Combine
 10→import Kingfisher
 11→import UIKit
 12→
 13→struct MediaProvider: MediaProviderProtocol {
 14→    private let mediaLoader: MediaLoaderProtocol
 15→    private let imageCache: Kingfisher.ImageCache
 16→    private let homeserverReachabilityPublisher: CurrentValuePublisher<NetworkMonitorReachability, Never>?
 17→    
 18→    init(mediaLoader: MediaLoaderProtocol,
 19→         imageCache: Kingfisher.ImageCache,
 20→         homeserverReachabilityPublisher: CurrentValuePublisher<NetworkMonitorReachability, Never>?) {
 21→        self.mediaLoader = mediaLoader
 22→        self.imageCache = imageCache
 23→        self.homeserverReachabilityPublisher = homeserverReachabilityPublisher
 24→    }
 25→    
 26→    // MARK: Images
 27→    
 28→    func imageFromSource(_ source: MediaSourceProxy?, size: CGSize?) -> UIImage? {
 29→        guard let url = source?.url else {
 30→            return nil
 31→        }
 32→        let cacheKey = cacheKeyForURL(url, size: size)
 33→        return imageCache.retrieveImageInMemoryCache(forKey: cacheKey, options: nil)
 34→    }
 35→    
 36→    func loadImageFromSource(_ source: MediaSourceProxy, size: CGSize?) async -> Result<UIImage, MediaProviderError> {
 37→        if let image = imageFromSource(source, size: size) {
 38→            return .success(image)
 39→        }
 40→        
 41→        let cacheKey = cacheKeyForURL(source.url, size: size)
 42→        
 43→        if let cacheResult = try? await imageCache.retrieveImage(forKey: cacheKey, options: nil),
 44→           let image = cacheResult.image {
 45→            return .success(image)
 46→        }
 47→
 48→        do {
 49→            let imageData: Data
 50→            if let size {
 51→                imageData = try await mediaLoader.loadMediaThumbnailForSource(source, width: UInt(size.width), height: UInt(size.height))
 52→            } else {
 53→                imageData = try await mediaLoader.loadMediaContentForSource(source)
 54→            }
 55→
 56→            guard let image = UIImage(data: imageData) else {
 57→                MXLog.error("Invalid image data")
 58→                return .failure(.invalidImageData)
 59→            }
 60→
 61→            try await imageCache.store(image, forKey: cacheKey)
 62→
 63→            return .success(image)
 64→        } catch {
 65→            MXLog.error("Failed retrieving image with error: \(error)")
 66→            return .failure(.failedRetrievingImage)
 67→        }
 68→    }
 69→    
 70→    func loadImageRetryingOnReconnection(_ source: MediaSourceProxy, size: CGSize?) -> Task<UIImage, any Error> {
 71→        guard let homeserverReachabilityPublisher else {
 72→            fatalError("This method shouldn't be invoked without a homeserver reachability publisher set.")
 73→        }
 74→        
 75→        return Task {
 76→            if case let .success(image) = await loadImageFromSource(source, size: size) {
 77→                return image
 78→            }
 79→            
 80→            guard !Task.isCancelled else {
 81→                throw MediaProviderError.cancelled
 82→            }
 83→            
 84→            for await reachability in homeserverReachabilityPublisher.values {
 85→                guard !Task.isCancelled else {
 86→                    throw MediaProviderError.cancelled
 87→                }
 88→                
 89→                guard reachability == .reachable else {
 90→                    continue
 91→                }
 92→                
 93→                switch await loadImageFromSource(source, size: size) {
 94→                case .success(let image):
 95→                    return image
 96→                case .failure:
 97→                    // If it fails after a retry with the network available
 98→                    // then something else must be wrong. Bail out.
 99→                    if reachability == .reachable {
100→                        throw MediaProviderError.cancelled
101→                    }
102→                }
103→            }
104→            
105→            throw MediaProviderError.cancelled
106→        }
107→    }
108→    
109→    func loadImageDataFromSource(_ source: MediaSourceProxy) async -> Result<Data, MediaProviderError> {
110→        do {
111→            let imageData = try await mediaLoader.loadMediaContentForSource(source)
112→            return .success(imageData)
113→        } catch {
114→            MXLog.error("Failed retrieving image with error: \(error)")
115→            return .failure(.failedRetrievingImage)
116→        }
117→    }
118→    
119→    // MARK: Files
120→    
121→    func loadFileFromSource(_ source: MediaSourceProxy, filename: String?) async -> Result<MediaFileHandleProxy, MediaProviderError> {
122→        do {
123→            let file = try await mediaLoader.loadMediaFileForSource(source, filename: filename)
124→            return .success(file)
125→        } catch {
126→            MXLog.error("Failed retrieving file with error: \(error)")
127→            return .failure(.failedRetrievingFile)
128→        }
129→    }
130→    
131→    // MARK: Thumbnail
132→    
133→    func loadThumbnailForSource(source: MediaSourceProxy, size: CGSize) async -> Result<Data, MediaProviderError> {
134→        do {
135→            let thumbnailData = try await mediaLoader.loadMediaThumbnailForSource(source, width: UInt(size.width), height: UInt(size.height))
136→            return .success(thumbnailData)
137→        } catch {
138→            MXLog.error("Failed retrieving image with error: \(error)")
139→            return .failure(.failedRetrievingThumbnail)
140→        }
141→    }
142→    
143→    // MARK: - Private
144→    
145→    private func cacheKeyForURL(_ url: URL, size: CGSize?) -> String {
146→        if let size {
147→            return "\(url.absoluteString){\(size.width),\(size.height)}"
148→        } else {
149→            return url.absoluteString
150→        }
151→    }
152→}
