 9→import Combine
10→import Foundation
11→import UIKit
12→
13→@preconcurrency import MatrixRustSDK
14→
15→private final class MediaRequest {
16→    var continuations: [CheckedContinuation<Data, Error>] = []
17→}
18→
19→actor MediaLoader: MediaLoaderProtocol {
20→    // We noticed that the keyboard appears to hold onto a reference to the `Context` of the last
21→    // screen that had text input focus, resulting in its MediaProvider staying alive which in
22→    // turn keeps this loader alive: https://github.com/element-hq/element-x-ios/issues/4465
23→    // Therefore the client is `weak` so that the underlying `MatrixRustSDK.Client` is released
24→    // when e.g. clearing the cache, otherwise we have the potential for 2 `Client`s to be alive
25→    // at the same time causing havoc.
26→    //
27→    // Whilst a more correct fix would be to make `Context.mediaProvider` weak, this requires a
28→    // bunch of workarounds in our preview tests to keep the mock provider alive as some ViewModels
29→    // don't have an accompanying ClientMock to own it.
30→    private weak var client: ClientProtocol?
31→    private var ongoingRequests = [MediaSourceProxy: MediaRequest]()
32→
33→    init(client: ClientProtocol) {
34→        self.client = client
35→    }
36→    
37→    func loadMediaContentForSource(_ source: MediaSourceProxy) async throws -> Data {
38→        try await enqueueLoadMediaRequest(forSource: source) { [weak client] in
39→            guard let client else { throw MediaLoaderError.missingClient }
40→            return try await client.getMediaContent(mediaSource: source.underlyingSource)
41→        }
42→    }
43→    
44→    func loadMediaThumbnailForSource(_ source: MediaSourceProxy, width: UInt, height: UInt) async throws -> Data {
45→        try await enqueueLoadMediaRequest(forSource: source) { [weak client] in
46→            guard let client else { throw MediaLoaderError.missingClient }
47→            return try await client.getMediaThumbnail(mediaSource: source.underlyingSource, width: UInt64(width), height: UInt64(height))
48→        }
49→    }
50→    
51→    func loadMediaFileForSource(_ source: MediaSourceProxy, filename: String?) async throws -> MediaFileHandleProxy {
52→        guard let client else { throw MediaLoaderError.missingClient }
53→        let result = try await client.getMediaFile(mediaSource: source.underlyingSource,
54→                                                   filename: filename,
55→                                                   mimeType: source.mimeType ?? "application/octet-stream",
56→                                                   useCache: true,
57→                                                   tempDir: nil)
58→        
59→        return MediaFileHandleProxy(handle: result)
60→    }
61→    
62→    // MARK: - Private
63→    
64→    private func enqueueLoadMediaRequest(forSource source: MediaSourceProxy, operation: @escaping () async throws -> Data) async throws -> Data {
65→        if let ongoingRequest = ongoingRequests[source] {
66→            return try await withCheckedThrowingContinuation { continuation in
67→                ongoingRequest.continuations.append(continuation)
68→            }
69→        }
70→        
71→        let ongoingRequest = MediaRequest()
72→        ongoingRequests[source] = ongoingRequest
73→        
74→        defer {
75→            ongoingRequests[source] = nil
76→        }
77→        
78→        do {
79→            let result = try await operation()
80→            
81→            ongoingRequest.continuations.forEach { $0.resume(returning: result) }
82→            
83→            return result
84→            
85→        } catch {
86→            ongoingRequest.continuations.forEach { $0.resume(throwing: error) }
87→            throw error
88→        }
89→    }
90→}
