 11→struct LoadableAvatarImage: View {
 12→    private let url: URL?
 13→    private let name: String?
 14→    private let contentID: String
 15→    private let isSpace: Bool
 16→    private let avatarSize: Avatars.Size
 17→    private let mediaProvider: MediaProviderProtocol?
 18→    private let onTap: ((URL) -> Void)?
 19→    
 20→    @ScaledMetric private var frameSize: CGFloat
 21→    
 22→    init(url: URL?,
 23→         name: String?,
 24→         contentID: String,
 25→         isSpace: Bool = false,
 26→         avatarSize: Avatars.Size,
 27→         mediaProvider: MediaProviderProtocol?,
 28→         onTap: ((URL) -> Void)? = nil) {
 29→        self.url = url
 30→        self.name = name
 31→        self.contentID = contentID
 32→        self.isSpace = isSpace
 33→        self.avatarSize = avatarSize
 34→        self.mediaProvider = mediaProvider
 35→        self.onTap = onTap
 36→        
 37→        _frameSize = ScaledMetric(wrappedValue: avatarSize.value)
 38→    }
 39→    
 40→    var body: some View {
 41→        if let onTap, let url {
 42→            Button {
 43→                onTap(url)
 44→            } label: {
 45→                clippedAvatar
 46→            }
 47→            .buttonStyle(.borderless) // Add a button style to stop the whole row being tappable.
 48→        } else {
 49→            clippedAvatar
 50→        }
 51→    }
 52→    
 53→    private var clippedAvatar: some View {
 54→        avatar
 55→            .frame(width: frameSize, height: frameSize)
 56→            .background(Color.compound.bgCanvasDefault)
 57→            .clipAvatar(isSpace: isSpace, scaledSize: _frameSize)
 58→            .environment(\.shouldAutomaticallyLoadImages, true) // We always load avatars.
 59→    }
 60→    
 61→    @ViewBuilder
 62→    private var avatar: some View {
 63→        if let url {
 64→            LoadableImage(url: url,
 65→                          mediaType: .avatar,
 66→                          size: avatarSize.scaledSize,
 67→                          mediaProvider: mediaProvider) { image in
 68→                image
 69→                    .scaledToFill()
 70→            } placeholder: {
 71→                PlaceholderAvatarImage(name: name, contentID: contentID)
 72→            }
 73→        } else {
 74→            PlaceholderAvatarImage(name: name, contentID: contentID)
 75→        }
 76→    }
 77→}
 78→
 79→extension View {
 80→    func clipAvatar(isSpace: Bool, size: CGFloat) -> some View {
 81→        modifier(ClipAvatarModifier(isSpace: isSpace, size: size))
 82→    }
 83→    
 84→    func clipAvatar(isSpace: Bool, scaledSize: ScaledMetric<CGFloat>) -> some View {
 85→        modifier(ClipAvatarModifier(isSpace: isSpace, scaledSize: scaledSize))
 86→    }
 87→}
 88→
 89→struct ClipAvatarModifier: ViewModifier {
 90→    private let isSpace: Bool
 91→    @ScaledMetric private var scaledSize: CGFloat
 92→    
 93→    init(isSpace: Bool, size: CGFloat) {
 94→        self.isSpace = isSpace
 95→        _scaledSize = ScaledMetric(wrappedValue: size)
 96→    }
 97→    
 98→    init(isSpace: Bool, scaledSize: ScaledMetric<CGFloat>) {
 99→        self.isSpace = isSpace
100→        _scaledSize = scaledSize
101→    }
102→    
103→    func body(content: Content) -> some View {
104→        content
105→            .clipShape(avatarShape)
106→    }
107→    
108→    private var avatarShape: some Shape {
109→        isSpace ? AnyShape(RoundedRectangle(cornerRadius: scaledSize / 4)) : AnyShape(Circle())
110→    }
111→}
