 14→/// Used to configure animations
 15→enum LoadableImageMediaType: Equatable {
 16→    /// An avatar (can be displayed anywhere within the app).
 17→    case avatar
 18→    /// An image displayed in the timeline.
 19→    case timelineItem(uniqueID: TimelineItemIdentifier.UniqueID)
 20→    /// Any other media (can be displayed anywhere within the app).
 21→    case generic
 22→}
 23→
 24→struct LoadableImage<TransformerView: View, PlaceholderView: View>: View {
 25→    private let mediaSource: MediaSourceProxy?
 26→    private let mediaType: LoadableImageMediaType
 27→    private let blurhash: String?
 28→    private let size: CGSize?
 29→    private let mediaProvider: MediaProviderProtocol?
 30→    private let transformer: (AnyView) -> TransformerView
 31→    private let placeholder: () -> PlaceholderView
 32→    
 33→    /// A SwiftUI view that automatically fetches images
 34→    /// It will try fetching the image from in-memory cache and if that's not available
 35→    /// it will fire a task to load it through the image provider
 36→    /// - Parameters:
 37→    ///   - mediaSource: the source of the image
 38→    ///   - blurhash: an optional blurhash
 39→    ///   - transformer: entry point for configuring the resulting image view
 40→    ///   - placeholder: a view to show while the image or blurhash are not available
 41→    init(mediaSource: MediaSourceProxy,
 42→         mediaType: LoadableImageMediaType = .generic,
 43→         blurhash: String? = nil,
 44→         size: CGSize? = nil,
 45→         mediaProvider: MediaProviderProtocol?,
 46→         transformer: @escaping (AnyView) -> TransformerView = { $0 },
 47→         placeholder: @escaping () -> PlaceholderView) {
 48→        self.mediaSource = mediaSource
 49→        self.mediaType = mediaType
 50→        self.blurhash = blurhash
 51→        self.size = size
 52→        self.mediaProvider = mediaProvider
 53→        self.transformer = transformer
 54→        self.placeholder = placeholder
 55→    }
 56→    
 57→    init(url: URL,
 58→         mediaType: LoadableImageMediaType = .generic,
 59→         blurhash: String? = nil,
 60→         size: CGSize? = nil,
 61→         mediaProvider: MediaProviderProtocol?,
 62→         transformer: @escaping (AnyView) -> TransformerView = { $0 },
 63→         placeholder: @escaping () -> PlaceholderView) {
 64→        mediaSource = try? MediaSourceProxy(url: url, mimeType: nil)
 65→        self.mediaType = mediaType
 66→        self.blurhash = blurhash
 67→        self.size = size
 68→        self.mediaProvider = mediaProvider
 69→        self.transformer = transformer
 70→        self.placeholder = placeholder
 71→    }
 72→    
 73→    var body: some View {
 74→        if let mediaSource {
 75→            LoadableImageContent(mediaSource: mediaSource,
 76→                                 mediaType: mediaType,
 77→                                 blurhash: blurhash,
 78→                                 size: size,
 79→                                 mediaProvider: mediaProvider,
 80→                                 transformer: transformer,
 81→                                 placeholder: placeholder)
 82→                .id(stableMediaIdentifier)
 83→        } else {
 84→            placeholder()
 85→        }
 86→    }
 87→    
 88→    private var stableMediaIdentifier: String? {
 89→        switch mediaType {
 90→        case .timelineItem(let uniqueID):
 91→            // Consider media for the same item to be the same view
 92→            uniqueID.value
 93→        default:
 94→            // Binds the lifecycle of the LoadableImage to the associated URL.
 95→            // This fixes the problem of the cache returning old values after a change in the URL.
 96→            mediaSource?.url.absoluteString
 97→        }
 98→    }
 99→}
100→
101→private struct LoadableImageContent<TransformerView: View, PlaceholderView: View>: View, ImageDataProvider {
102→    @Environment(\.shouldAutomaticallyLoadImages) private var loadAutomatically
103→    
104→    private let mediaSource: MediaSourceProxy
105→    private let mediaType: LoadableImageMediaType
106→    private let blurhash: String?
107→    private let transformer: (AnyView) -> TransformerView
108→    private let placeholder: () -> PlaceholderView
109→    
110→    @StateObject private var contentLoader: ContentLoader
111→    @State private var loadManually = false
112→    
113→    init(mediaSource: MediaSourceProxy,
114→         mediaType: LoadableImageMediaType,
115→         blurhash: String? = nil,
116→         size: CGSize? = nil,
117→         mediaProvider: MediaProviderProtocol?,
118→         transformer: @escaping (AnyView) -> TransformerView,
119→         placeholder: @escaping () -> PlaceholderView) {
120→        assert(mediaProvider != nil, "Missing image provider, make sure one has been supplied to the view model.")
121→        
122→        self.mediaSource = mediaSource
123→        self.mediaType = mediaType
124→        self.blurhash = blurhash
125→        self.transformer = transformer
126→        self.placeholder = placeholder
127→        _contentLoader = StateObject(wrappedValue: ContentLoader(mediaSource: mediaSource, size: size, mediaProvider: mediaProvider))
128→    }
129→    
130→    var shouldRender: Bool {
131→        loadAutomatically || loadManually
132→    }
133→    
134→    var body: some View {
135→        ZStack {
136→            switch (contentLoader.content, shouldRender) {
137→            case (.image(let image), true):
138→                transformer(
139→                    AnyView(Image(uiImage: image).resizable())
140→                )
141→            case (.gifData, true):
142→                transformer(AnyView(KFAnimatedImage(source: .provider(self))))
143→            case (.none, _), (_, false):
144→                if let blurHashView {
145→                    if shouldRender {
146→                        transformer(blurHashView)
147→                    } else {
148→                        blurHashView
149→                    }
150→                } else {
151→                    placeholder().overlay { placeholderOverlay }
152→                }
153→            }
154→        }
155→        .animation(mediaType == .avatar ? .noAnimation : .elementDefault, value: contentLoader.content)
156→        .animation(.elementDefault, value: loadManually)
157→        .task(id: mediaSource.url.absoluteString + "\(shouldRender)") {
158→            guard shouldRender, contentLoader.content == nil else {
159→                return
160→            }
161→            
162→            await contentLoader.load()
163→        }
164→        .onDisappear {
165→            guard contentLoader.content == nil else {
166→                return
167→            }
168→            
169→            contentLoader.cancel()
170→        }
171→    }
172→    
173→    // Note: Returns `AnyView` as this is what `transformer` expects.
174→    var blurHashView: AnyView? {
175→        if let blurhash,
176→           // Build a small blurhash image so that it's fast
177→           let image = UIImage(blurHash: blurhash, size: .init(width: 10.0, height: 10.0)) {
178→            return AnyView(Image(uiImage: image).resizable().overlay { blurHashOverlay })
179→        } else {
180→            return nil
181→        }
182→    }
183→    
184→    // MARK: - Overlays
185→    
186→    @ViewBuilder
187→    var placeholderOverlay: some View {
188→        switch mediaType {
189→        case .avatar, .generic:
190→            EmptyView()
191→        case .timelineItem:
192→            if shouldRender {
193→                ProgressView(L10n.commonLoading)
194→                    .frame(maxWidth: .infinity)
195→            } else {
196→                loadManuallyButton
197→            }
198→        }
199→    }
200→    
201→    @ViewBuilder
202→    var blurHashOverlay: some View {
203→        if !shouldRender {
204→            loadManuallyButton
205→        }
206→    }
207→    
208→    var loadManuallyButton: some View {
209→        ZStack {
210→            Color.black.opacity(0.6)
211→                .contentShape(.rect)
212→                .onTapGesture { /* Empty gesture to block the `mediaTapped` action */ }
213→            
214→            // Don't use a real Button as it sometimes triggers simultaneously with the long press gesture.
215→            Text(L10n.actionShow)
216→                .font(.compound.bodyLGSemibold)
217→                .foregroundStyle(.compound.textOnSolidPrimary)
218→                .padding(.horizontal, 16)
219→                .padding(.vertical, 4)
220→                .overlay {
221→                    Capsule()
222→                        .stroke(lineWidth: 1)
223→                        .foregroundStyle(.compound.borderInteractiveSecondary)
224→                }
225→                .contentShape(.capsule)
226→                .onTapGesture {
227→                    loadManually = true
228→                }
229→                .environment(\.colorScheme, .light)
230→        }
231→    }
232→    
233→    // MARK: - ImageDataProvider
234→    
235→    var cacheKey: String {
236→        mediaSource.url.absoluteString
237→    }
238→    
239→    func data(handler: @escaping (Result<Data, Error>) -> Void) {
240→        guard case let .gifData(data) = contentLoader.content else {
241→            fatalError("Shouldn't reach this point without any gif data")
242→        }
243→        
244→        handler(.success(data))
245→    }
246→}
