248→private class ContentLoader: ObservableObject {
249→    enum Content: Equatable {
250→        case image(UIImage)
251→        case gifData(Data)
252→    }
253→    
254→    private let mediaProvider: MediaProviderProtocol?
255→    private let mediaSource: MediaSourceProxy
256→    private let size: CGSize?
257→    private var imageLoadingCancellable: AnyCancellable?
258→    
259→    @Published private var cachedContent: Content?
260→    
261→    var content: Content? {
262→        if cachedContent != nil {
263→            return cachedContent
264→        }
265→        
266→        if isGIF {
267→            if let image = mediaProvider?.imageFromSource(mediaSource),
268→               let data = image.kf.data(format: .GIF) {
269→                return .gifData(data)
270→            }
271→        } else if let image = mediaProvider?.imageFromSource(mediaSource, size: size) {
272→            return .image(image)
273→        }
274→        
275→        return cachedContent
276→    }
277→    
278→    init(mediaSource: MediaSourceProxy, size: CGSize?, mediaProvider: MediaProviderProtocol?) {
279→        self.mediaSource = mediaSource
280→        self.size = size
281→        self.mediaProvider = mediaProvider
282→    }
283→    
284→    @MainActor
285→    func load() async {
286→        if isGIF {
287→            if case let .success(data) = await mediaProvider?.loadImageDataFromSource(mediaSource) {
288→                cachedContent = .gifData(data)
289→            }
290→        } else {
291→            guard let task = mediaProvider?.loadImageRetryingOnReconnection(mediaSource, size: size) else {
292→                MXLog.error("Failed loading image, invalid reconnection retry task.")
293→                return
294→            }
295→            
296→            imageLoadingCancellable = task.asCancellable()
297→            
298→            if let image = try? await task.value {
299→                cachedContent = .image(image)
300→            }
301→        }
302→    }
303→    
304→    func cancel() {
305→        imageLoadingCancellable?.cancel()
306→    }
307→    
308→    private var isGIF: Bool {
309→        mediaSource.mimeType == "image/gif"
310→    }
311→}
312→
313→extension EnvironmentValues {
314→    /// Whether or not images should be loaded inside `LoadableImage` without a user interaction.
315→    @Entry var shouldAutomaticallyLoadImages = true
316→}
